import base64,hashlib,json,os,resource,subprocess,sys,tempfile
COMMAND=["gh","workflow","run","sdk240-host-setup.yml","--repo","inflatable-cookie/swallowtail","--ref","main"]

def dispatch(packet,receipt):
    if packet["reservedEffects"][2]["command"]!=COMMAND or packet["dispatchFence"]["ref"]!="main":
        raise ValueError("fixed_main_dispatch_required")
    expected=receipt["workflowCommit"]
    if len(expected)!=40 or any(c not in "0123456789abcdef" for c in expected):
        raise ValueError("exact_registration_commit_required")
    for key,value in (("workflowBlobSha256",packet["workflowBlobSha256"]),("sourceCommit",packet["sourceCommit"]),("sourceRecordSha256",packet["sourceRecord"]["sha256"])):
        if receipt[key]!=value: raise ValueError("registration_binding_drift")
    workflow_id=receipt["workflowId"]
    if type(workflow_id) is not int or workflow_id!=packet["workflowBase"]["workflowId"]: raise ValueError("registry_identity_required")
    def get(suffix):
        def limit(): resource.setrlimit(resource.RLIMIT_FSIZE,(1048576,1048576))
        with tempfile.TemporaryFile(dir=os.environ["TMPDIR"]) as output:
            subprocess.run(["gh","api","repos/inflatable-cookie/swallowtail/"+suffix],stdout=output,stderr=subprocess.STDOUT,preexec_fn=limit,check=True,timeout=30)
            output.seek(0);raw=output.read(1048577)
        if len(raw)>1048576: raise ValueError("preflight_output_bound")
        return json.loads(raw)
    registry=get("actions/workflows/"+str(workflow_id))
    if registry["id"]!=workflow_id or registry["state"]!="active" or registry["path"]!=packet["workflowPath"]: raise ValueError("registry_drift")
    workflow=get("contents/"+packet["workflowPath"]+"?ref=main")
    if workflow["sha"]!=packet["workflowGitBlob"] or hashlib.sha256(base64.b64decode(workflow["content"])).hexdigest()!=packet["workflowBlobSha256"]: raise ValueError("workflow_drift")
    for name,digest in ((packet["sourceRecord"]["path"],packet["sourceRecord"]["sha256"]),("scripts/claude-agent-sdk-bootstrap-session.py",packet["bootstrapSha256"])):
        item=get("contents/"+name+"?ref="+packet["sourceCommit"])
        if hashlib.sha256(base64.b64decode(item["content"])).hexdigest()!=digest: raise ValueError("executable_input_drift")
    history=get("actions/workflows/"+str(workflow_id)+"/runs?event=workflow_dispatch&per_page=100")
    prior=packet["dispatchFence"]["expectedPriorAttempts"]
    keys=("id","event","head_sha","run_attempt","status","conclusion")
    if history["total_count"]!=len(prior) or [{key:r[key] for key in keys} for r in history["workflow_runs"]]!=prior: raise ValueError("attempt_history_drift")
    # Last remote observation is the comparison fence, never a --ref argument.
    if get("git/ref/heads/main")["object"]["sha"]!=expected: raise ValueError("main_ref_drift")
    return subprocess.run(COMMAND,check=True,timeout=45)

def verify_run(receipt,run):
    if run["workflow_id"]!=receipt["workflowId"] or run["head_sha"]!=receipt["workflowCommit"] or run["event"]!="workflow_dispatch" or run["run_attempt"]!=1:
